import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

dict_ops.code:
def merge_max(d1, d2):
    out = dict(d1)
    for k, v in d2.items():
        out[k] = max(out.get(k, v), v)
    return out

recursion.code:
def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def fib(n):
    if n <= 1:
        return n
    return fib(n-1) + fib(n-2)

def fact(n):
    if n <= 1:
        return 1
    return n * fact(n-1)

def deep_sum(x):
    if isinstance(x, int):
        return x
    return sum(deep_sum(i) for i in x)
